// New customer (bill-to, ship-to or both) or a new ship-to on an existing
// bill-to. Eclipse first, then HubSpot through "E Customers → HS"
// (7RvySfhLM96IcGZC), then the HubSpot-only fields.
const b = $input.first().json.body || {};
const s = (v) => String(v == null ? '' : v).trim();
const bad = (msg) => [{ json: { ok: false, statusCode: 400, body: { success: false, error: msg } } }];

const flags = (Array.isArray(b.billto_shipto_flag) ? b.billto_shipto_flag : s(b.billto_shipto_flag).split(';'))
  .map(s).filter((f) => f === 'bill_to' || f === 'ship_to');
const input = {
  name: s(b.name),
  domain: s(b.domain).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, ''),
  isBillTo: flags.includes('bill_to'),
  isShipTo: flags.includes('ship_to'),
  address: s(b.address),
  address2: s(b.address2),
  city: s(b.city),
  state: s(b.state).toUpperCase(),
  zip: s(b.zip).replace(/[\s-]/g, ''),
  propane: s(b.e_propane_customer),
  industry: s(b.industry),
  description: s(b.description),
  billToId: s(b.bill_to_id),
  hsOwnerId: s(b.hs_owner_id),
  eUserId: s(b.e_user_id).toUpperCase(),
  // Picked on the page from the rep's territories (like an order's).
  outsideSales: s(b.outside_salesperson),
  // From Google Address Validation in the check (latitude / longitude on
  // the HubSpot company; customer-lookup uses them for branch distances).
  lat: b.latitude === '' || b.latitude == null ? null : Number(b.latitude),
  lng: b.longitude === '' || b.longitude == null ? null : Number(b.longitude),
  emails: (Array.isArray(b.emails) ? b.emails : []).map(s).filter(Boolean),
  phones: (Array.isArray(b.phones) ? b.phones : [])
    .map((p) => ({ number: s(p && p.number), description: s(p && p.description) }))
    .filter((p) => p.number),
};

if (!input.name) return bad('Enter a name.');
if (!input.isBillTo && !input.isShipTo) return bad('Pick Bill To, Ship To or both.');
if (!input.address || !input.city || !input.state || !input.zip) return bad('Enter the street address, city, state and zip.');
if (!/^[A-Z]{2}$/.test(input.state)) return bad('State must be a 2-letter code.');
if (!/^\d{5}(\d{4})?$/.test(input.zip)) return bad('Zip must be 5 or 9 digits.');
if (input.propane !== 'yes' && input.propane !== 'no') return bad('Pick Propane or Not Propane.');
const shipOnly = input.isShipTo && !input.isBillTo;
if (shipOnly && !/^\d+$/.test(input.billToId)) return bad('A ship-to needs its bill-to.');
if (!shipOnly) input.billToId = '';
const coord = (v, max) => typeof v === 'number' && isFinite(v) && Math.abs(v) <= max;
if (!coord(input.lat, 90) || !coord(input.lng, 180)) { input.lat = null; input.lng = null; }
const badEmail = input.emails.find((e) => !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e));
if (badEmail) return bad('Not a valid email: ' + badEmail);
const badPhone = input.phones.find((p) => p.number.replace(/\D/g, '').length < 7);
if (badPhone) return bad('Not a valid phone number: ' + badPhone.number);

return [{ json: { ok: true, input, shipOnly } }];

// Same defaults as format_customer in "HS Customer → E"
// (Pm8oaApE4sJDrA6F), from the rep's HubSpot user (found by e_user_id;
// 2026-10-30, the page's hs_owner_id was blank for every rep), plus emails
// and phones. Outside sales is the rep's pick on the page when sent.
// isBillto / isShipto are spelled as in that flow (a live create,
// execution 244776, came back isBillTo / isShipTo true).
const v = $('Validate').first().json;
const inp = v.input;
const fail = (code, msg) => [{ json: { ok: false, statusCode: code, body: { success: false, error: msg } } }];

// Bill-to check for a ship-to only customer.
if (v.shipOnly) {
  const env = $('Eclipse: get bill-to').first().json || {};
  if (env.error) return fail(502, 'Eclipse bill-to lookup failed: ' + env.error + (env.message ? ' ' + JSON.stringify(env.message).slice(0, 300) : ''));
  const bill = (Array.isArray(env.results) ? env.results[0] : env) || {};
  if (!bill.id) return fail(404, 'Eclipse customer ' + inp.billToId + ' not found.');
  if (bill.isBillTo !== true) return fail(400, 'Customer ' + bill.id + ' (' + (bill.name || '') + ') is not a bill-to.');
}

// User lookup is best-effort: no user (or a failed lookup) falls back to
// the page's Eclipse user as writer and the flow's own defaults.
const fu = $('HubSpot: find user').first().json || {};
const user = (!fu.error && Array.isArray(fu.results) && fu.results[0]) || null;
const op = (user && user.properties) || {};
const name = inp.name;
const c = {
  name,
  addressLine1: inp.address,
  city: inp.city,
  state: inp.state,
  postalCode: inp.zip,
  isBillto: inp.isBillTo,
  isShipto: inp.isShipTo,
  sortBy: name.toLowerCase().substring(0, 12),
  nameIndex: name.toLowerCase().substring(0, 12),
  types: inp.propane === 'yes' ? [{ type: 'PROPANE' }] : [],
  defaultPriceClass: inp.propane === 'yes' ? 'LVL-3' : 'LVL-4',
  outsideSalesperson: inp.outsideSales || op.e_user_default_territory || 'WIHOUSE',
  writer: op.e_user_id || inp.eUserId || 'BECCHR',
  homeBranch: op.e_user_default_branch || '1',
};
if (inp.address2) c.addressLine2 = inp.address2;
if (op.e_user_default_sales_source_id) c.salesSource = op.e_user_default_sales_source_id;
if (v.shipOnly) c.billToId = inp.billToId;
if (inp.emails.length) c.emails = inp.emails.map((address) => ({ address }));
if (inp.phones.length) c.phones = inp.phones.map((p) => (p.description ? { number: p.number, description: p.description } : { number: p.number }));

return [{ json: { ok: true, customer: c, ownerFound: !!user } }];

// Eclipse's create answers with the new customer at the top level
// (execution 244776 of Pm8oaApE4sJDrA6F); an error goes back word for word.
const r = $input.first().json || {};
const v = $('Validate').first().json;
const created = (Array.isArray(r.results) ? r.results[0] : r) || {};
if (r.error || !created.id) {
  const m = r.message;
  const text = (m && m.errors && m.errors[0] && m.errors[0].message) || (typeof m === 'string' ? m : (m ? JSON.stringify(m).slice(0, 500) : '')) || r.error || 'Eclipse returned no customer id.';
  return [{ json: { ok: false, statusCode: 502, body: { success: false, step: 'eclipse', error: 'Eclipse did not create the customer: ' + String(text).replace(/\r?\n/g, ' ') } } }];
}
const id = String(created.id);
return [{
  json: {
    ok: true,
    id,
    // A new ship-to on an existing bill-to: make sure the bill-to lists it.
    linkBillTo: v.shipOnly,
    // E Customers → HS reads both, so the bill-to's ship-to list and the
    // Bill To association update in HubSpot too.
    customer_ids: [id].concat(v.shipOnly ? [v.input.billToId] : []).join(','),
    created: {
      e_customer_id: id,
      name: created.name || v.input.name,
      is_bill_to: created.isBillTo === true,
      is_ship_to: created.isShipTo === true,
      bill_to_id: v.shipOnly ? v.input.billToId : (created.isBillTo ? id : ''),
      home_branch: String(created.homeBranch || ''),
      price_class: String(created.defaultPriceClass || ''),
      terms: String(created.defaultTerms || ''),
    },
  },
}];

// Re-read bill-to: when Eclipse did not add the new ship-to to the
// bill-to's shipToLists by itself (UNVERIFIED either way), append it.
// customer-lookup lists a bill-to's ship-tos from shipToLists.
const env = $input.first().json || {};
const k = $('Check create').first().json;
const bill = (Array.isArray(env.results) ? env.results[0] : env) || {};
if (env.error || !bill.id) {
  return [{ json: { update: false, warning: 'Could not re-read bill-to ' + $('Validate').first().json.input.billToId + ' to check its ship-to list: ' + (env.error || 'not found') } }];
}
const ids = (bill.shipToLists || []).map((x) => String((x && (x.shipToId != null ? x.shipToId : x.id)) || '')).filter(Boolean);
if (ids.includes(k.id)) return [{ json: { update: false } }];
return [{ json: { update: true, billToId: String(bill.id), shipToLists: ids.concat([k.id]).join(',') } }];

// HubSpot-only fields, written after "E Customers → HS" has made the
// company (matched by e_customer_id). Not name: that flow writes HubSpot's
// composite "Name - Bill/Ship - AG - City, ST - id".
const inp = $('Validate').first().json.input;
const props = { e_propane_customer: inp.propane };
if (inp.domain) props.domain = inp.domain;
if (inp.industry) props.industry = inp.industry;
if (inp.description) props.description = inp.description;
// Owner: the page's hs_owner_id, else the rep's owner from HubSpot: owner id
// (owners by userId = the user's hs_internal_user_id).
const ow = $('HubSpot: owner id').first().json || {};
const ownerId = inp.hsOwnerId || (!ow.error && ow.objectFound !== false && ow.id ? String(ow.id) : '');
if (ownerId) props.hubspot_owner_id = ownerId;
if (inp.lat != null && inp.lng != null) { props.latitude = String(inp.lat); props.longitude = String(inp.lng); }
return [{ json: { id: $('Check create').first().json.id, props } }];

// The customer exists in Eclipse by now, so anything after the create that
// fails is a warning, not an error.
const k = $('Check create').first().json;
const warnings = [];
if (!$('Build').first().json.ownerFound) warnings.push('No HubSpot user has Eclipse id ' + ($('Validate').first().json.input.eUserId || '(none)') + ', so home branch and sales source used the defaults.');
if ($('Link to bill-to?').isExecuted) {
  const l = $('Plan bill-to link').first().json;
  if (l.warning) warnings.push(l.warning);
  if (l.update && $('Eclipse: add to bill-to').isExecuted) {
    const u = $('Eclipse: add to bill-to').first().json || {};
    if (u.error) warnings.push('The ship-to was created but could not be added to bill-to ' + l.billToId + "'s ship-to list: " + u.error);
  }
}
const sync = $('HubSpot sync (E Customers → HS)').first().json || {};
if (sync.error) warnings.push('HubSpot sync failed (' + String(sync.error.message || sync.error).slice(0, 200) + '); the company should still show in HubSpot within a few minutes.');
const hs = $('HubSpot: set company fields').first().json || {};
let hsId = '';
if (hs.error) warnings.push('HubSpot domain, industry, description, propane, owner and map location were not saved: ' + String(hs.error).slice(0, 300));
else hsId = String(hs.id || '');
return [{ json: { statusCode: 200, body: Object.assign({ success: true, hs_id: hsId, warnings }, k.created) } }];
